	i := len(vm.globals)
	vm.globalIdx[name] = i
	vm.globals = append(vm.globals, undefV)
	vm.globalNames = append(vm.globalNames, name)
	return i
}

func (vm *VM) defineNative(name string, fn func([]Value) Value) {
	vm.globals[vm.globalSlot(name)] = objV(&ObjNative{Obj: Obj{kNative}, fn: fn, name: name})
}

func (vm *VM) interpret(src string) int {
	fn := compile(vm, src)
	if fn == nil {
		return 65
	}
	cl := &ObjClosure{Obj: Obj{kClosure}, fn: fn}
	vm.stack[0] = objV(cl)
	vm.sp = 1
	vm.frames[0] = CallFrame{closure: cl, ip: 0, base: 0}
	vm.frameCount = 1
	if !vm.run() {
		return 70
	}
	return 0
}

func (vm *VM) runtimeError(format string, args ...any) {
	vm.out.Flush()
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	for i := vm.frameCount - 1; i >= 0; i-- {
		f := &vm.frames[i]
		fn := f.closure.fn
		line := fn.chunk.lines[f.ip-1]
		if fn.name == nil {
			fmt.Fprintf(os.Stderr, "[line %d] in script\n", line)
		} else {
			fmt.Fprintf(os.Stderr, "[line %d] in %s()\n", line, fn.name.s)
		}
	}
	vm.openUpvalues = nil
}

func (vm *VM) captureUpvalue(slot int) *ObjUpvalue {
	var prev *ObjUpvalue
	u := vm.openUpvalues
	for u != nil && u.slot > slot {
		prev = u
		u = u.next
	}
	if u != nil && u.slot == slot {
		return u
	}
	nu := &ObjUpvalue{Obj: Obj{kUpvalue}, loc: &vm.stack[slot], slot: slot, next: u}
	if prev == nil {
		vm.openUpvalues = nu
	} else {
		prev.next = nu
	}
	return nu
}

func (vm *VM) closeUpvalues(last int) {
	for vm.openUpvalues != nil && vm.openUpvalues.slot >= last {
		u := vm.openUpvalues
		u.closed = *u.loc
		u.loc = &u.closed
		vm.openUpvalues = u.next
	}
}

// pushFrame sets up a call to closure cl whose callee slot is at base.
func (vm *VM) pushFrame(cl *ObjClosure, argc int, base int) bool {
	if argc != cl.fn.arity {
		vm.runtimeError("Expected %d arguments but got %d.", cl.fn.arity, argc)
		return false
	}
	if vm.frameCount == FramesMax || base+frameReserve > StackMax {
		vm.runtimeError("Stack overflow.")
		return false
	}
	f := &vm.frames[vm.frameCount]
	vm.frameCount++
	f.closure = cl
	f.ip = 0
	f.base = base
	return true
}

// callValue handles calls of non-closure (or closure) values. vm.sp must be
// current; it is updated on return.
func (vm *VM) callValue(callee Value, argc int) bool {
	base := vm.sp - 1 - argc
	if callee.p != nil {
		switch callee.kind() {
		case kClosure:
			return vm.pushFrame(callee.asClosure(), argc, base)
		case kBoundMethod:
			b := callee.asBound()
			vm.stack[base] = b.receiver
			return vm.pushFrame(b.method, argc, base)
		case kClass:
			c := callee.asClass()
			inst := &ObjInstance{Obj: Obj{kInstance}, class: c, shape: rootShape}
			if c.fieldHint > 0 {
				inst.fields = make([]Value, 0, c.fieldHint)
			}
			vm.stack[base] = objV(inst)
			if c.init != nil {
				return vm.pushFrame(c.init, argc, base)
			}
			if argc != 0 {
				vm.runtimeError("Expected 0 arguments but got %d.", argc)
				return false
			}
			vm.sp = base + 1
			return true
		case kNative:
			n := callee.asNative()
			r := n.fn(vm.stack[base+1 : vm.sp])
			vm.stack[base] = r
			vm.sp = base + 1
			return true
		}
	}
	vm.runtimeError("Can only call functions and classes.")
	return false
}

func (vm *VM) run() bool {
	stack := vm.stack
	frames := vm.frames
	globals := vm.globals
	sp := vm.sp
	frame := &frames[vm.frameCount-1]
	cl := frame.closure
	code := cl.fn.chunk.code
	consts := cl.fn.chunk.consts
	caches := cl.fn.caches
	ip := frame.ip
	base := frame.base

	for {
		op := code[ip]
		ip++
		switch op {
		case OpConstant:
			stack[sp] = consts[code[ip]]
			ip++
			sp++
		case OpNil:
			stack[sp] = nilV
			sp++
		case OpTrue:
			stack[sp] = trueV
			sp++
		case OpFalse:
			stack[sp] = falseV
			sp++
		case OpPop:
			sp--
		case OpGetLocal:
			stack[sp] = stack[base+int(code[ip])]
			ip++
			sp++
		case OpSetLocal:
			stack[base+int(code[ip])] = stack[sp-1]
			ip++
		case OpGetGlobal:
			idx := int(code[ip])<<8 | int(code[ip+1])
			ip += 2
			v := globals[idx]
			if v.p == undefP {
				frame.ip = ip
				vm.runtimeError("Undefined variable '%s'.", vm.globalNames[idx])
				return false
			}
			stack[sp] = v
			sp++
		case OpDefineGlobal:
			idx := int(code[ip])<<8 | int(code[ip+1])
			ip += 2
			globals[idx] = stack[sp-1]
			sp--
		case OpSetGlobal:
			idx := int(code[ip])<<8 | int(code[ip+1])
			ip += 2
			if globals[idx].p == undefP {
				frame.ip = ip
				vm.runtimeError("Undefined variable '%s'.", vm.globalNames[idx])
				return false
			}
			globals[idx] = stack[sp-1]
		case OpGetUpvalue:
			stack[sp] = *cl.upvalues[code[ip]].loc
			ip++
			sp++
		case OpSetUpvalue:
			*cl.upvalues[code[ip]].loc = stack[sp-1]
			ip++
		case OpGetProperty:
			recv := stack[sp-1]
			ci := int(code[ip+1])<<8 | int(code[ip+2])
			if !recv.isObj(kInstance) {
				frame.ip = ip + 3
				vm.runtimeError("Only instances have properties.")
				return false
			}
			inst := recv.asInstance()
			c := &caches[ci]
			if inst.shape == c.shape {
				stack[sp-1] = inst.fields[c.idx]
				ip += 3
				continue
			}
			name := consts[code[ip]].asString()
			ip += 3
			if i := inst.shape.lookup(name); i >= 0 {
				c.shape = inst.shape
				c.idx = i
				stack[sp-1] = inst.fields[i]
				continue
			}
			m := inst.class.methods[name]
			if m == nil {
				frame.ip = ip
				vm.runtimeError("Undefined property '%s'.", name.s)
				return false
			}
			stack[sp-1] = objV(&ObjBoundMethod{Obj: Obj{kBoundMethod}, receiver: recv, method: m})
		case OpSetProperty:
			recv := stack[sp-2]
			ci := int(code[ip+1])<<8 | int(code[ip+2])
			if !recv.isObj(kInstance) {
				frame.ip = ip + 3
				vm.runtimeError("Only instances have fields.")
				return false
			}
			inst := recv.asInstance()
			v := stack[sp-1]
			c := &caches[ci]
			if inst.shape == c.shape {
				if c.newShape == nil {
					inst.fields[c.idx] = v
				} else {
					inst.fields = append(inst.fields, v)
					inst.shape = c.newShape
				}
			} else {
				name := consts[code[ip]].asString()
				if i := inst.shape.lookup(name); i >= 0 {
					inst.fields[i] = v
					c.shape, c.idx, c.newShape = inst.shape, i, nil
				} else {
					old := inst.shape
					ns := old.add(name)
					inst.fields = append(inst.fields, v)
					inst.shape = ns
					c.shape, c.idx, c.newShape = old, len(inst.fields)-1, ns
					if len(inst.fields) > inst.class.fieldHint {
						inst.class.fieldHint = len(inst.fields)
					}
				}
			}
			ip += 3
			stack[sp-2] = v
			sp--
		case OpGetSuper:
			name := consts[code[ip]].asString()
			ip++
			super := stack[sp-1].asClass()
			sp--
			m := super.methods[name]
			if m == nil {
				frame.ip = ip
				vm.runtimeError("Undefined property '%s'.", name.s)
				return false
			}
			stack[sp-1] = objV(&ObjBoundMethod{Obj: Obj{kBoundMethod}, receiver: stack[sp-1], method: m})
		case OpEqual:
			stack[sp-2] = boolV(valuesEqual(stack[sp-2], stack[sp-1]))
			sp--
		case OpNotEqual:
			stack[sp-2] = boolV(!valuesEqual(stack[sp-2], stack[sp-1]))
			sp--
		case OpGreater:
			a, b := stack[sp-2], stack[sp-1]
			if a.p != nil || b.p != nil {
				frame.ip = ip
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			stack[sp-2] = boolV(a.n > b.n)
			sp--
		case OpGreaterEqual:
			a, b := stack[sp-2], stack[sp-1]
			if a.p != nil || b.p != nil {
				frame.ip = ip
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			stack[sp-2] = boolV(a.n >= b.n)
			sp--
		case OpLess:
			a, b := stack[sp-2], stack[sp-1]
			if a.p != nil || b.p != nil {
				frame.ip = ip
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			stack[sp-2] = boolV(a.n < b.n)
			sp--
		case OpLessEqual:
			a, b := stack[sp-2], stack[sp-1]
			if a.p != nil || b.p != nil {
				frame.ip = ip
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			stack[sp-2] = boolV(a.n <= b.n)
			sp--
		case OpAdd:
			a, b := stack[sp-2], stack[sp-1]
			if a.p == nil && b.p == nil {
				stack[sp-2] = Value{n: a.n + b.n}
			} else if a.isObj(kString) && b.isObj(kString) {
				s := &ObjString{Obj: Obj{kString}, s: a.asString().s + b.asString().s}
				stack[sp-2] = objV(s)
			} else {
				frame.ip = ip
				vm.runtimeError("Operands must be two numbers or two strings.")
				return false
			}
			sp--
		case OpSubtract:
			a, b := stack[sp-2], stack[sp-1]
			if a.p != nil || b.p != nil {
				frame.ip = ip
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			stack[sp-2] = Value{n: a.n - b.n}
			sp--
		case OpMultiply:
			a, b := stack[sp-2], stack[sp-1]
			if a.p != nil || b.p != nil {
				frame.ip = ip
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			stack[sp-2] = Value{n: a.n * b.n}
			sp--
		case OpDivide:
			a, b := stack[sp-2], stack[sp-1]
			if a.p != nil || b.p != nil {
				frame.ip = ip
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			stack[sp-2] = Value{n: a.n / b.n}
			sp--
		case OpNot:
			stack[sp-1] = boolV(stack[sp-1].isFalsey())
		case OpNegate:
			if stack[sp-1].p != nil {
				frame.ip = ip
				vm.runtimeError("Operand must be a number.")
				return false
			}
			stack[sp-1].n = -stack[sp-1].n
		case OpPrint:
			sp--
			vm.out.WriteString(formatValue(stack[sp]))
			vm.out.WriteByte('\n')
		case OpJump:
			ip += int(code[ip])<<8 | int(code[ip+1]) + 2
		case OpJumpIfFalse:
			if stack[sp-1].isFalsey() {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			} else {
				ip += 2
			}
		case OpLoop:
			ip -= int(code[ip])<<8 | int(code[ip+1]) - 2
		case OpCall:
			argc := int(code[ip])
			ip++
			frame.ip = ip
			callee := stack[sp-1-argc]
			if callee.isObj(kClosure) {
				if !vm.pushFrame(callee.asClosure(), argc, sp-1-argc) {
					return false
				}
			} else {
				vm.sp = sp
				if !vm.callValue(callee, argc) {
					return false
				}
				sp = vm.sp
			}
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpInvoke:
			name := consts[code[ip]].asString()
			argc := int(code[ip+1])
			ci := int(code[ip+2])<<8 | int(code[ip+3])
			ip += 4
			frame.ip = ip
			recv := stack[sp-1-argc]
			if !recv.isObj(kInstance) {
				vm.runtimeError("Only instances have methods.")
				return false
			}
			inst := recv.asInstance()
			c := &caches[ci]
			var m *ObjClosure
			if inst.shape == c.shape && inst.class == c.class {
				m = c.method
			} else if i := inst.shape.lookup(name); i >= 0 {
				stack[sp-1-argc] = inst.fields[i]
				vm.sp = sp
				if !vm.callValue(inst.fields[i], argc) {
					return false
				}
				sp = vm.sp
				m = nil
			} else {
				m = inst.class.methods[name]
				if m == nil {
					vm.runtimeError("Undefined property '%s'.", name.s)
					return false
				}
				c.shape, c.class, c.method = inst.shape, inst.class, m
			}
			if m != nil {
				if !vm.pushFrame(m, argc, sp-1-argc) {
					return false
				}
			}
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpSuperInvoke:
			name := consts[code[ip]].asString()
			argc := int(code[ip+1])
			ip += 2
			frame.ip = ip
			super := stack[sp-1].asClass()
			sp--
			m := super.methods[name]
			if m == nil {
				vm.runtimeError("Undefined property '%s'.", name.s)
				return false
			}
			if !vm.pushFrame(m, argc, sp-1-argc) {
				return false
			}
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpClosure:
			fn := consts[code[ip]].asFunction()
			ip++
			ncl := &ObjClosure{Obj: Obj{kClosure}, fn: fn}
			if fn.upvalueCount > 0 {
				ncl.upvalues = make([]*ObjUpvalue, fn.upvalueCount)
				for i := range ncl.upvalues {
					isLocal := code[ip]
					index := int(code[ip+1])
					ip += 2
					if isLocal == 1 {
						ncl.upvalues[i] = vm.captureUpvalue(base + index)
					} else {
						ncl.upvalues[i] = cl.upvalues[index]
					}
				}
			}
			stack[sp] = objV(ncl)
			sp++
		case OpCloseUpvalue:
			vm.closeUpvalues(sp - 1)
			sp--
		case OpReturn:
			result := stack[sp-1]
			if vm.openUpvalues != nil {
				vm.closeUpvalues(base)
			}
			vm.frameCount--
			if vm.frameCount == 0 {
				vm.sp = 0
				return true
			}
			sp = base
			stack[sp] = result
			sp++
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpClass:
			name := consts[code[ip]].asString()
			ip++
			c := &ObjClass{Obj: Obj{kClass}, name: name, methods: make(map[*ObjString]*ObjClosure)}
			stack[sp] = objV(c)
			sp++
		case OpInherit:
			superV := stack[sp-2]
			if !superV.isObj(kClass) {
				frame.ip = ip
				vm.runtimeError("Superclass must be a class.")
				return false
			}
			super := superV.asClass()
			sub := stack[sp-1].asClass()
			for k, v := range super.methods {
				sub.methods[k] = v
			}
			sub.init = super.init
			sp--
		case OpMethod:
			name := consts[code[ip]].asString()
			ip++
			c := stack[sp-2].asClass()
			m := stack[sp-1].asClosure()
			c.methods[name] = m
			if name == vm.initString {
				c.init = m
			}
			sp--
		}
	}
}

