			argc := int(code[ip])
			ip++
			frame.ip = ip
			callee := stack[sp-1-argc]
			if callee.isObj(kClosure) {
				ncl := callee.asClosure()
				nb := sp - 1 - argc
				if argc != ncl.fn.arity || vm.frameCount == FramesMax || nb+frameReserve > StackMax {
					vm.pushFrame(ncl, argc, nb)
					return false
				}
				frame = &frames[vm.frameCount]
				vm.frameCount++
				frame.closure = ncl
				frame.base = nb
				cl = ncl
				code = ncl.fn.chunk.code
				consts = ncl.fn.chunk.consts
				caches = ncl.fn.caches
				ip = 0
				base = nb
				continue
			} else {
				vm.sp = sp
				if !vm.callValue(callee, argc) {
					return false
				}
				sp = vm.sp
			}
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpInvoke:
			name := consts[code[ip]].asString()
			argc := int(code[ip+1])
			ci := int(code[ip+2])<<8 | int(code[ip+3])
			ip += 4
			frame.ip = ip
			recv := stack[sp-1-argc]
			if !recv.isObj(kInstance) {
				vm.runtimeError("Only instances have methods.")
				return false
			}
			inst := recv.asInstance()
			c := &caches[ci]
			var m *ObjClosure
			if inst.shape == c.shape && inst.class == c.class {
				m = c.method
				nb := sp - 1 - argc
				if argc != m.fn.arity || vm.frameCount == FramesMax || nb+frameReserve > StackMax {
					vm.pushFrame(m, argc, nb)
					return false
				}
				frame = &frames[vm.frameCount]
				vm.frameCount++
				frame.closure = m
				frame.base = nb
				cl = m
				code = m.fn.chunk.code
				consts = m.fn.chunk.consts
				caches = m.fn.caches
				ip = 0
				base = nb
				continue
			} else if i := inst.shape.lookup(name); i >= 0 {
				stack[sp-1-argc] = inst.fields[i]
				vm.sp = sp
				if !vm.callValue(inst.fields[i], argc) {
					return false
				}
				sp = vm.sp
				m = nil
			} else {
				m = inst.class.methods[name]
				if m == nil {
					vm.runtimeError("Undefined property '%s'.", name.s)
					return false
				}
				c.shape, c.class, c.method = inst.shape, inst.class, m
			}
			if m != nil {
				if !vm.pushFrame(m, argc, sp-1-argc) {
					return false
				}
			}
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpSuperInvoke:
			name := consts[code[ip]].asString()
			argc := int(code[ip+1])
			ip += 2
			frame.ip = ip
			super := stack[sp-1].asClass()
			sp--
			m := super.methods[name]
			if m == nil {
				vm.runtimeError("Undefined property '%s'.", name.s)
				return false
			}
			if !vm.pushFrame(m, argc, sp-1-argc) {
				return false
			}
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpClosure:
			fn := consts[code[ip]].asFunction()
			ip++
			ncl := &ObjClosure{Obj: Obj{kClosure}, fn: fn}
			if fn.upvalueCount > 0 {
				ncl.upvalues = make([]*ObjUpvalue, fn.upvalueCount)
				for i := range ncl.upvalues {
					isLocal := code[ip]
					index := int(code[ip+1])
					ip += 2
					if isLocal == 1 {
						ncl.upvalues[i] = vm.captureUpvalue(base + index)
					} else {
						ncl.upvalues[i] = cl.upvalues[index]
					}
				}
			}
			stack[sp] = objV(ncl)
			sp++
		case OpCloseUpvalue:
			vm.closeUpvalues(sp - 1)
			sp--
		case OpReturn:
			result := stack[sp-1]
			if vm.openUpvalues != nil {
				vm.closeUpvalues(base)
			}
			vm.frameCount--
			if vm.frameCount == 0 {
				vm.sp = 0
				return true
			}
			sp = base
			stack[sp] = result
			sp++
			frame = &frames[vm.frameCount-1]
			cl = frame.closure
			code = cl.fn.chunk.code
			consts = cl.fn.chunk.consts
			caches = cl.fn.caches
			ip = frame.ip
			base = frame.base
		case OpGreaterJump:
			a, b := stack[sp-2], stack[sp-1]
			sp -= 2
			if a.p != nil || b.p != nil {
				frame.ip = ip - 2
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			if a.n > b.n {
				ip += 2
			} else {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			}
		case OpGreaterEqualJump:
			a, b := stack[sp-2], stack[sp-1]
			sp -= 2
			if a.p != nil || b.p != nil {
				frame.ip = ip - 2
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			if a.n >= b.n {
				ip += 2
			} else {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			}
		case OpLessJump:
			a, b := stack[sp-2], stack[sp-1]
			sp -= 2
			if a.p != nil || b.p != nil {
				frame.ip = ip - 2
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			if a.n < b.n {
				ip += 2
			} else {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			}
		case OpLessEqualJump:
			a, b := stack[sp-2], stack[sp-1]
			sp -= 2
			if a.p != nil || b.p != nil {
				frame.ip = ip - 2
				vm.runtimeError("Operands must be numbers.")
				return false
			}
			if a.n <= b.n {
				ip += 2
			} else {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			}
		case OpEqualJump:
			sp -= 2
			if valuesEqual(stack[sp], stack[sp+1]) {
				ip += 2
			} else {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			}
		case OpNotEqualJump:
			sp -= 2
			if !valuesEqual(stack[sp], stack[sp+1]) {
				ip += 2
			} else {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			}
		case OpJumpIfFalsePop:
			sp--
			if stack[sp].isFalsey() {
				ip += int(code[ip])<<8 | int(code[ip+1]) + 2
			} else {
				ip += 2
			}
		case OpSetLocalPop:
			sp--
			stack[base+int(code[ip])] = stack[sp]
			ip++
		case OpSetGlobalPop:
			idx := int(code[ip])<<8 | int(code[ip+1])
			ip += 2
			if globals[idx].p == undefP {
				frame.ip = ip
				vm.runtimeError("Undefined variable '%s'.", vm.globalNames[idx])
