			recv := stack[sp-2]
			if !recv.isObj(kInstance) {
				frame.ip = ip + 3
				vm.runtimeError("Only instances have fields.")
				return false
			}
			inst := recv.asInstance()
			c := &caches[int(code[ip+1])<<8|int(code[ip+2])]
			if inst.shape == c.shape && c.newShape == nil {
				inst.fields[c.idx] = stack[sp-1]
			} else {
