			recv := stack[base+int(code[ip])]
			ip++
			if !recv.isObj(kInstance) {
				frame.ip = ip + 3
				vm.runtimeError("Only instances have properties.")
				return false
			}
			inst := recv.asInstance()
			c := &caches[int(code[ip+1])<<8|int(code[ip+2])]
			if inst.shape == c.shape {
				stack[sp] = inst.fields[c.idx]
				sp++
				ip += 3
				continue
			}
			name := consts[code[ip]].asString()
			ip += 3
			v, ok := vm.getProperty(inst, name, c)
			if !ok {
				frame.ip = ip
				vm.runtimeError("Undefined property '%s'.", name.s)
				return false
			}
			stack[sp] = v
			sp++
		case OpClass:
			name := consts[code[ip]].asString()
			ip++
			c := &ObjClass{Obj: Obj{kClass}, name: name, methods: make(map[*ObjString]*ObjClosure)}
			stack[sp] = objV(c)
			sp++
		case OpInherit:
			superV := stack[sp-2]
			if !superV.isObj(kClass) {
				frame.ip = ip
				vm.runtimeError("Superclass must be a class.")
				return false
			}
			super := superV.asClass()
			sub := stack[sp-1].asClass()
			for k, v := range super.methods {
				sub.methods[k] = v
			}
			sub.init = super.init
			sp--
		case OpMethod:
			name := consts[code[ip]].asString()
			ip++
			c := stack[sp-2].asClass()
			m := stack[sp-1].asClosure()
			c.methods[name] = m
			if name == vm.initString {
				c.init = m
			}
			sp--
		}
	}
}

func (vm *VM) getProperty(inst *ObjInstance, name *ObjString, c *PropCache) (Value, bool) {
	if i := inst.shape.lookup(name); i >= 0 {
		c.shape = inst.shape
		c.idx = i
		return inst.fields[i], true
	}
	m := inst.class.methods[name]
	if m == nil {
		return nilV, false
	}
	return objV(&ObjBoundMethod{Obj: Obj{kBoundMethod}, receiver: objV(inst), method: m}), true
}

func (vm *VM) setProperty(inst *ObjInstance, name *ObjString, v Value, c *PropCache) {
	if inst.shape == c.shape {
		inst.fields = append(inst.fields, v)
		inst.shape = c.newShape
		return
	}
	if i := inst.shape.lookup(name); i >= 0 {
		inst.fields[i] = v
		c.shape, c.idx, c.newShape = inst.shape, i, nil
		return
	}
	old := inst.shape
	ns := old.add(name)
	inst.fields = append(inst.fields, v)
	inst.shape = ns
	c.shape, c.idx, c.newShape = old, len(inst.fields)-1, ns
	if len(inst.fields) > inst.class.fieldHint {
		inst.class.fieldHint = len(inst.fields)
	}
}

// newInstance allocates an instance together with inline storage for the
// number of fields instances of its class have been seen to use.
func newInstance(c *ObjClass) *ObjInstance {
	var inst *ObjInstance
	switch n := c.fieldHint; {
	case n == 0:
		inst = &ObjInstance{}
	case n == 1:
		o := &struct {
			ObjInstance
			a [1]Value
		}{}
		o.fields = o.a[:0]
		inst = &o.ObjInstance
	case n == 2:
		o := &struct {
			ObjInstance
			a [2]Value
		}{}
		o.fields = o.a[:0]
		inst = &o.ObjInstance
	case n <= 4:
		o := &struct {
			ObjInstance
			a [4]Value
		}{}
		o.fields = o.a[:0]
		inst = &o.ObjInstance
	case n <= 6:
		o := &struct {
			ObjInstance
			a [6]Value
		}{}
		o.fields = o.a[:0]
		inst = &o.ObjInstance
	case n <= 8:
		o := &struct {
			ObjInstance
			a [8]Value
		}{}
		o.fields = o.a[:0]
		inst = &o.ObjInstance
	default:
		inst = &ObjInstance{fields: make([]Value, 0, n)}
	}
	inst.kind = kInstance
	inst.class = c
	inst.shape = rootShape
	return inst
}

